package com.farika.soundflow;
import android.app.*;import android.content.*;import android.os.*;import android.net.Uri;import androidx.media3.datasource.DataSource;import androidx.media3.exoplayer.drm.DefaultDrmSessionManager;import java.lang.reflect.*;import java.util.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import org.robolectric.android.controller.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,application=Application.class)
public class LocalPlayer168Test {
 public static class FakePlayer extends PlaybackService {volatile String preparedUri="";volatile long preparedPosition;protected LocalAudioStore localAudioStore(){return new LocalAudio168Test.SyntheticStore(this);}protected void prepare(String uri,int ticket,boolean hls,DataSource.Factory data,DefaultDrmSessionManager drm){preparedPosition=position();preparedUri=uri;}}
 Context c;LocalAudio168Test.SyntheticStore store;ServiceController<FakePlayer> ctrl;FakePlayer s;
 @Before public void setup(){c=RuntimeEnvironment.getApplication();LocalAudio168Test.SyntheticStore.reset();store=new LocalAudio168Test.SyntheticStore(c);ctrl=Robolectric.buildService(FakePlayer.class).create();s=ctrl.get();}
 @After public void cleanup(){ctrl.destroy();PlaybackService.instance=null;}
 LocalAudioStore.Entry add(String n,long pos)throws Exception{LocalAudioStore.Entry e=store.add(Uri.parse("content://synthetic.audio/"+n),LocalAudioStore.READ);store.position(e.uri(),pos,180000);return store.get(e.uri());}
 void set(String n,Object value)throws Exception{Field f=PlaybackService.class.getDeclaredField(n);f.setAccessible(true);f.set(s,value);}void play(LocalAudioStore.Entry... e){ArrayList<String> q=new ArrayList<>();for(LocalAudioStore.Entry one:e)q.add(one.uri());s.onStartCommand(new Intent("PLAY").putExtra("uri",e[0].uri()).putStringArrayListExtra("queue",q).putExtra("playlistContext",true),0,1);}
 void waitUri(String expected)throws Exception{long until=System.currentTimeMillis()+5000;while(System.currentTimeMillis()<until){Shadows.shadowOf(Looper.getMainLooper()).idle();if(expected.equals(s.preparedUri))return;Thread.sleep(10);}fail("No local prepare: "+s.error);}
 @Test public void localReferenceResolvesToDocumentAndSavedPosition()throws Exception{LocalAudioStore.Entry e=add("a",48000);play(e);waitUri(e.document);assertEquals(48000,s.preparedPosition);assertEquals(48000,store.get(e.uri()).position);assertFalse(s.preparedUri.startsWith("local:"));}
 @Test public void skipsSaveAndRestoreIndependentBookmarks()throws Exception{LocalAudioStore.Entry a=add("a",48000),b=add("b",30000);play(a,b);waitUri(a.document);set("pendingPosition",60000L);s.next();waitUri(b.document);assertEquals(60000,store.get(a.uri()).position);assertEquals(30000,s.preparedPosition);s.skipPrevious();waitUri(a.document);assertEquals(60000,s.preparedPosition);assertEquals(30000,store.get(b.uri()).position);}
 @Test public void pauseAndExplicitCloseKeepPerFilePosition()throws Exception{LocalAudioStore.Entry a=add("a",48000);play(a);waitUri(a.document);set("pendingPosition",51000L);s.pause();assertEquals(51000,store.get(a.uri()).position);s.stopForLocalChange();assertEquals(51000,store.get(a.uri()).position);assertNull(PlaybackCheckpoint.read(c));}
 @Test public void endBookmarkResetsOnlyCompletedFile()throws Exception{LocalAudioStore.Entry a=add("a",48000),b=add("b",30000);play(a,b);waitUri(a.document);set("pendingPosition",180000L);set("localEnded",true);s.checkpoint();assertEquals(0,store.get(a.uri()).position);assertEquals(30000,store.get(b.uri()).position);}
 @Test public void unavailableFileRetainsBookmarkAndExplainsFailure()throws Exception{LocalAudioStore.Entry a=add("a",48000);LocalAudio168Test.SyntheticStore.access.put(a.document,LocalAudioStore.Access.UNAVAILABLE);play(a);long until=System.currentTimeMillis()+5000;while(System.currentTimeMillis()<until&&s.error.isEmpty()){Shadows.shadowOf(Looper.getMainLooper()).idle();Thread.sleep(10);}assertTrue(s.error.contains("недоступен"));assertEquals(48000,store.get(a.uri()).position);assertEquals("",s.preparedUri);}
 @Test public void confirmedMissingFileDropsReferenceAndStops()throws Exception{LocalAudioStore.Entry a=add("a",48000);LocalAudio168Test.SyntheticStore.access.put(a.document,LocalAudioStore.Access.MISSING);play(a);long until=System.currentTimeMillis()+5000;while(System.currentTimeMillis()<until&&!s.current.isEmpty()){Shadows.shadowOf(Looper.getMainLooper()).idle();Thread.sleep(10);}assertNull(store.get(a.uri()));assertEquals("",s.current);assertNull(PlaybackCheckpoint.read(c));}
}
